struct VSOut { float4 SvPos : SV_Position; float3 WorldPos : TEXCOORD1; float3 Normal : TEXCOORD2; float4 Color : TEXCOORD3; float2 UV : TEXCOORD4; float4 ShadowPos : TEXCOORD5; float4 ShadowPosNr : TEXCOORD6; float AtlasLayer : TEXCOORD7; };
float4 MainPS(VSOut IN) : SV_Target
{
    float2 cell = floor(IN.WorldPos.xz / 2.0);
    float parity = fmod(abs(cell.x + cell.y), 2.0);
    float3 darkTile = float3(0.008, 0.008, 0.010);
    float3 lightTile = float3(0.94, 0.94, 0.92);
    return float4(lerp(darkTile, lightTile, parity), 1.0);
}
